let pendingCloud:State|null=null;
let gallery:GalleryItem[]|null=null,board:{name:string;score:number;mine:boolean}[]|null=null;
const refreshGallery=()=>{listGallery().then(g=>{gallery=g;render();}).catch(()=>{});};
const refreshBoard=()=>{leaderboard(dailyKey()).then(b=>{board=b;render();}).catch(()=>{});};
let puzzle:{def:Puzzle;main:State;daily:boolean;won:boolean;score?:number}|null=null;
import {persist,restore,serialize,deserialize,SAVE_KEY} from './save.ts';
import {t,translateDOM,setLanguage,formatNumber,formatCompact} from './i18n.ts';
import {startEffects,readEffects,writeEffects,enableSound,enableMusic} from './juice.ts';
import {readPreferences,writePreferences,defaultPreferences,rememberGuideProgress} from './onboarding.ts';
import {onboardingPanel,guidePage} from './guide-view.ts';
