import {compareLayouts,BENCH_KEY,type Comparison} from './bench.ts';
import {benchPage} from './bench-view.ts';
import {diagnosis,routeWarning,insertionHint,supplyHint,lotDetails,observeChange,changePanel,type ChangeObservation} from './insights.ts';
import {startChallenge,updateChallenge} from './challenges.ts';
import {challengeCards,challengeNotice} from './challenge-view.ts';
let observation:ChangeObservation|null=null;
// When the game is hosted on claude.ai, files are saved through the viewer's downloads capability.
let hostDownloads:{save(r:{filename:string;data:string}):Promise<unknown>}|null=null;
try{(globalThis as any).claude?.use?.('downloads')?.then((d:typeof hostDownloads)=>{hostDownloads=d;}).catch(()=>{});}catch{}
let benchReference:State|null=null,benchResult:Comparison|null=null,benchDuration=180;
try{const raw=localStorage.getItem(BENCH_KEY);if(raw)benchReference=deserialize(raw);}catch{}
let preferences=defaultPreferences();
let effects={sound:false,volume:.5};
let meta:Meta=readMeta(globalThis.localStorage??({getItem:()=>null} as unknown as Storage));
const ghostBase:Meta=structuredClone(meta);
const saveMeta=()=>{try{writeMeta(localStorage,meta);}catch{}};
const applyDisplay=()=>{const root=document.documentElement;root.dataset.skin=meta.theme;root.style.setProperty('--zoom',String(meta.zoom));root.classList.toggle('high-contrast',meta.contrast);};
try{effects=readEffects(localStorage);}catch{}
try{preferences=readPreferences(localStorage);}catch{}
setLanguage(preferences.language);
const savePreferences=()=>{try{return writePreferences(localStorage,preferences);}catch{return false;}};
const $=<T extends Element=HTMLElement>(q:string)=>document.querySelector<T>(q)!;
let state:State=createState(),storageBlocked=false;
try{const saved=restore(localStorage);state=saved.state??state;storageBlocked=saved.blocked;if(saved.warning)setTimeout(()=>toast(saved.warning),200);}catch{storageBlocked=true;setTimeout(()=>toast('Stockage local indisponible. Utilisez l’export JSON.'),200);}
let view='atelier',plant:PlantId='A',selectedLane=state.plants.A.lanes[0]?.id??0,selectedMachine=0,lastSave='En attente',lastRender=0;
const esc=(x:unknown)=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const nf={format:formatNumber};
function fmt(n:number){return formatCompact(n);}
function time(t:number){const sec=Math.floor(t*.1);return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;}
function toast(text:string){$('#toast').textContent=t(text);$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),5500);}
function save(){const real=puzzle?puzzle.main:state;if(recordBest(meta,real))saveMeta();if(storageBlocked)return;try{persist(localStorage,real);lastSave=time(state.tick);return true;}catch(e){toast('Sauvegarde impossible : '+(e as Error).message);return false;}}
function lane(){return state.plants[plant].lanes.find(x=>x.id===selectedLane);}
function findMachine(){return lane()?.machines.find(x=>x.id===selectedMachine);}
const btn=(action:string,text:string,extra='',disabled=false)=>`<button data-action="${action}" ${extra} ${disabled?'disabled':''}>${text}</button>`;
function popup(title:string,body:string){const d=$<HTMLDialogElement>('#dialog');d.innerHTML=`<div class="dialog-head"><span class="eyebrow">CARNET DE LABORATOIRE</span>${btn('close','✕','aria-label="Fermer"')}</div><h2>${esc(title)}</h2>${body}`;translateDOM(d);if(!d.open)d.showModal();}
function ask(title:string,action:string,value=''){popup(title,`<form id="name-form" data-submit="${action}"><label>Nom <input name="name" maxlength="48" required value="${esc(value)}" autocomplete="off"></label><p class="muted">Les noms et plans restent sur cet ordinateur.</p><button class="primary" type="submit">Enregistrer</button></form>`);$<HTMLInputElement>('#name-form input').focus();}
function chart(){const h=state.history;const rates=h.slice(1).map((x,i)=>(x.total-h[i].total)/((x.tick-h[i].tick)*.1));const max=Math.max(1,...rates);const pts=rates.map((v,i)=>`${(i/Math.max(1,rates.length-1)*600).toFixed(1)},${(74-v/max*62).toFixed(1)}`).join(' ');return `<svg class="chart" viewBox="0 0 600 86" role="img" aria-label="Historique du débit par seconde sur les 120 dernières secondes"><path d="M0 74 H600 M0 42 H600 M0 10 H600" class="grid-line"/><polyline points="${pts}" class="chart-line"/></svg><div class="chart-labels"><span>−${Math.max(0,h.length-1)} s</span><span>Échelle auto · pic ${fmt(max)}/s</span><span>maintenant</span></div>`;}
const RESOURCE_ICONS:Record<Resource,string>={ore:'◈',energy:'ϟ',components:'⬡',residue:'♧',catalyst:'✧',plasma:'✺'};
function resourceNote(r:Resource){const p=state.plants[plant];
 if(r==='ore')return plant==='A'?`+${fmt(12*2**p.oreLevel)}/s · brut`:'Extraction propre à la Fonderie';
 if(r==='energy')return `+${fmt(plant==='A'&&state.challenges?.active?.id==='economy'?8:BASE_ENERGY[plant]*2**p.energyLevel)}/s · brut`;
 if(r==='components')return plant==='A'?'Budget commun de construction':'Construction sur budget Fonderie';
 if(r==='residue')return plant==='B'?'Entrée de la Serre':'Chaleur résiduelle exploitable';
 if(r==='catalyst')return plant==='C'?'Entrée de la Forge':'Activateur des procédés';
 return plant==='A'?'Surchauffe ×10 par lot':'Produit par la Forge';}
function resources(){const p=state.plants[plant];const list=(Object.keys(RESOURCE_NAMES) as Resource[]).filter(r=>r!=='plasma'||plantUnlocked(state,'C'));return `<div class="resources">${list.map(r=>`<button class="resource resource-${r}" data-action="resource" data-resource="${r}"><span class="resource-label"><i>${RESOURCE_ICONS[r]}</i>${RESOURCE_NAMES[r]}</span><strong data-live="stock" data-resource="${r}">${fmt(p.stock[r])}</strong><span class="muted">${resourceNote(r)}</span></button>`).join('')}</div>`;}
function nodeStat(m:Machine){
 if(m.kind==='batch')return `${fmt(buffer(m))} / ${m.param}`;
 if(m.kind==='charge')return `${m.param} s · ×${fmt(1+m.param/2)}`;
 if(m.kind==='cadence')return `accord ×${1+m.streak}`;
 if(m.kind==='filter')return `seuil ×${fmt(m.param)}`;
 if(m.kind==='compress')return `${m.queue.length} / ${m.param} lots`;
 if(m.kind==='furnace')return `chaleur ${fmt(m.heat??0)}`;
 if(m.kind==='mirror')return m.memory!==undefined?`reflet ×${fmt(m.memory)}`:'sans reflet';
 if(m.kind==='sensor')return `≥ ${fmt(m.param)} ${SENSOR_LABELS[m.variant??0]}`;
 if(m.kind==='stamp')return m.variant===1?'ambre':'cyan';
 return `${fmt(m.processed)} cycles`;}
const VARIANT_NAMES:Record<Variant,string>={standard:'Standard',slow:'Presses lentes',small:'Petits lots',nores:'Sans résonance'};
const SENSOR_LABELS=['énergie','catalyseurs','entrée','plasma'];
function machineCard(m:Machine,i:number){const def=MODULES[m.kind];const active=selectedMachine===m.id;const wait=/insuffisante|saturée|incompatible|ouverte|Choisir|Configurer|Relier/.test(m.status);return `<div class="node-wrap"><button class="node ${active?'selected':''} ${wait?'blocked':''} family-${family(m.kind)} ${flowActive(state,m)?'recent-flow':''} ${observation&&!observation.before.plants[plant].lanes.flatMap(l=>l.machines).some(n=>n.id===m.id)?'recent-install':''}" data-action="select-module" data-id="${m.id}"><span class="node-top"><span class="node-icon">${moduleSymbol(m.kind)}</span><small>${String(i+1).padStart(2,'0')}</small></span><strong>${def.name}</strong><span class="node-io">${def.input==='none'?(plant==='A'?'réserve matière':plant==='B'?'réserve résidus':'réserve catalyseurs'):def.input==='matter'?'matières · qualité':'fin de cycle'} → ${def.output==='matter'?'lot':'récupération'}</span><span class="node-stat">${nodeStat(m)}</span><progress max="${m.kind==='batch'||m.kind==='charge'?m.param:m.kind==='furnace'?100:m.kind==='compress'?m.param:1}" value="${m.kind==='batch'?Math.min(m.param,buffer(m)):m.kind==='charge'?Math.max(0,m.param-m.clock):m.kind==='furnace'?m.heat??0:m.kind==='compress'?Math.min(m.param,m.queue.length):m.clock>0?1-m.clock:0}"></progress><span class="node-status"><i></i>${esc(m.status)}</span><span class="node-buffer">Tampon : ${fmt(buffer(m))} / ${LIMITS.queue}</span>${incoming(state,m)>0?`<span class="transit-note">＋ ${fmt(incoming(state,m))} en transit</span>`:''}${m.lastPacket?`<span class="packet-detail">Dernier lot : ${fmt(m.lastPacket.qty)} · qualité ×${fmt(m.lastPacket.quality)} · ${fmt(m.lastPacket.marks)} empreintes</span>`:''}</button>${i<(lane()?.machines.length??0)-1?`<button class="connection ${m.connected?'':'disconnected'}" data-action="connect" data-id="${m.id}" title="${m.connected?'Déconnecter':'Relier'} la sortie" aria-label="${m.connected?'Déconnecter':'Relier'} la sortie de ${def.name}"><span>${m.connected?'→':'×'}</span><small>${def.output==='matter'?'lot':'cycle'}</small></button>`:'<span class="terminal">→<small>réserve</small></span>'}</div>`;}
function workshop(){const p=state.plants[plant],l=lane();return `<section class="panel workshop"><div class="section-head"><div><span class="eyebrow">COMPOSITION / ${plant==='A'?'FONDERIE':plant==='B'?'SERRE':'FORGE'}</span><h2>Atelier de procédés <span class="count">${p.lanes.length} / ${lanesMax(state)} lignes</span></h2></div>${btn('add-lane','＋ Nouvelle ligne','class="subtle"',p.lanes.length>=lanesMax(state)||state.plants.A.stock.components<costOf(state,'intake')+costOf(state,'press')+laneFee(state,plant))}</div>${networkOverview(state,plant,selectedLane)}<div class="lane-tabs">${p.lanes.map(x=>btn('select-lane',`${x.capsule?'▣':'⌘'} <span data-user-text>${esc(x.name)}</span>`,`data-id="${x.id}" class="${x.id===selectedLane?'active':''}"`)).join('')}</div>${l?`<div class="line-toolbar"><span><i class="dot"></i> ${l.capsule?'Invention active · états internes conservés':'Chaîne active · les sorties alimentent la carte suivante'}</span><div>${btn('save-config','Enregistrer la configuration')}${btn('encapsulate','▣ Encapsuler','',state.produced<1000)}${btn('remove-lane','Démonter','class="danger-text"')}</div></div>${routeWarning(l)?`<p class="flow-warning">${t(routeWarning(l))}</p>`:''}${l.capsule?`<div class="capsule-banner"><span>▣</span><div><strong><span data-user-text>${esc(l.name)}</span></strong><p>${l.machines.length} machines réelles · ${l.machines.reduce((a,m)=>a+m.paid,0)} composants immobilisés · ${fmt(l.machines.reduce((a,m)=>a+buffer(m),0))} matières internes</p></div>${btn('expand','Ouvrir l’invention')}</div>`:`<div class="node-strip">${l.machines.map(machineCard).join('')}</div>`}<div class="workshop-footer"><span>◌ Pas de temps : 100 ms</span><span>Réorganisation gratuite · démontage remboursé</span><span>${l.machines.length} / ${nodesMax(state)} machines</span></div>`:`<div class="empty">Une installation attend sa première chaîne.<br>Construisez une ligne pour la mettre en service.</div>`}</section>`;}
function inspector(){const m=findMachine();if(!m)return `<div class="panel inspector"><span class="eyebrow">OBSERVER → COMPRENDRE</span><h3>Chaque règle est visible.</h3><p>Sélectionnez une machine pour comprendre son cycle, modifier ses paramètres ou changer sa position.</p><div class="rule-note">Les flèches relient réellement les tampons. Cliquez sur une flèche pour interrompre ou rétablir une connexion.</div><p class="muted">Les modules s’ajoutent avant ou après la presse selon leur type d’entrée.</p></div>`;const d=MODULES[m.kind];return `<div class="panel inspector has-machine">${btn('deselect','✕','class="sheet-close" aria-label="Fermer"')}<span class="eyebrow">MACHINE ${m.id} / DÉTAIL DU PROCÉDÉ</span><h3><span class="teal">${d.icon}</span> ${d.name}</h3><p>${d.description}</p>${routingInspector(state,plant,lane(),m)}${lotDetails(state,plant,m)}${paramControls(m)}<dl><dt>État</dt><dd>${esc(m.status)}</dd><dt>Matières internes</dt><dd>${fmt(buffer(m))} / 800</dd><dt>Lots traités</dt><dd>${fmt(m.processed)}</dd><dt>Prochain cycle</dt><dd>${fmt(m.clock)} s</dd></dl><div class="inspector-actions">${btn('move','← Déplacer',`data-dir="-1"`)}${btn('move','Déplacer →',`data-dir="1"`)}</div>${!['intake','press'].includes(m.kind)?btn('remove-module',`Retirer · rendre ${m.paid} composants`,'class="wide danger-text"'):''}<p class="muted tiny">Déplacement entre cartes de même type. Les tampons et cycles suivent la machine.</p></div>`;}
const PARAM_LABELS:Partial<Record<Kind,string>>={intake:'Taille de livraison',batch:'Seuil de livraison',charge:'Durée de charge',filter:'Qualité minimale pour passer',compress:'Lots fondus ensemble',sensor:'Seuil de la réserve'};
function paramControls(m:Machine){
 const values=PARAMS[m.kind];let out='';
 if(values)out+=`<label>${PARAM_LABELS[m.kind]}<select data-param="${m.id}">${values.filter(x=>m.kind!=='batch'||x<=packetMax(state)).map(x=>`<option value="${x}" ${m.param===x?'selected':''}>${m.kind==='charge'?`${x} s · qualité ×${1+x/2}`:m.kind==='filter'?`×${fmt(x)}`:fmt(x)}</option>`).join('')}</select></label>`;
 if(m.kind==='stamp')out+=`<label>Couleur d’empreinte<select data-variant="${m.id}"><option value="0" ${(m.variant??0)===0?'selected':''}>Cyan</option><option value="1" ${m.variant===1?'selected':''} ${state.produced<3e6?'disabled':''}>Ambre${state.produced<3e6?' · 3 M cumulés':''}</option></select></label>`;
 if(m.kind==='sensor')out+=`<label>Réserve surveillée<select data-variant="${m.id}">${['Énergie','Catalyseurs','Entrée de l’installation','Plasma'].map((x,i)=>`<option value="${i}" ${(m.variant??0)===i?'selected':''}>${x}</option>`).join('')}</select></label>`;
 if(m.kind==='furnace')out+=`<p>Chaleur actuelle : <b>${fmt(m.heat??0)}</b> / 100 · qualité ×${fmt(1+(m.heat??0)/25)}</p>`;
 if(m.kind==='mirror')out+=`<p>${m.memory!==undefined?`Qualité retenue : ×${fmt(m.memory)}`:'Aucune qualité retenue pour l’instant.'}</p>`;
 return out;}
function catalog(){return `<section class="panel catalog"><div class="section-head"><div><span class="eyebrow">OUTILS D’EXPÉRIMENTATION</span><h2>Modules disponibles</h2></div><span class="muted">Ajouter à la ligne sélectionnée</span></div><div class="catalog-grid">${(Object.entries(MODULES) as [Kind,typeof MODULES[Kind]][]).filter(([k])=>!['intake','press'].includes(k)).sort((a,b)=>a[1].unlock-b[1].unlock).map(([k,d])=>{const lock=!unlocked(state,k);const cost=costOf(state,k);return `<article class="module-offer ${lock?'locked':''}" data-offer="${k}"><span class="module-icon">${lock?'⌑':moduleSymbol(k)}</span><div><h3>${d.name}</h3><p>${lock?(unlockAt(state,k)===Infinity?'Absent de ce mode de jeu':`Déblocage à ${fmt(unlockAt(state,k))} composants cumulés`):d.description.split('. ')[0]+'.'}</p>${insertionHint(lane(),k)?`<p class="offer-hint">${t(insertionHint(lane(),k))}</p>`:''}</div><div class="offer-actions">${btn('module-info','ⓘ',`data-kind="${k}" aria-label="Règles de ${d.name}"`)}${lock?'':btn('estimate','≈',`data-kind="${k}" title="Estimer l’effet sur 90 s" aria-label="Estimer l’effet de ${d.name}"`,!lane()||state.plants.A.stock.components<cost||(lane()?.machines.length??0)>=nodesMax(state))}${btn('add-module',lock?'Verrouillé':`＋ ${fmt(cost)}`,`data-kind="${k}"`,lock||!lane()||state.plants.A.stock.components<cost||(lane()?.machines.length??0)>=nodesMax(state))}</div></article>`;}).join('')}</div></section>`;}
function masteries(){
 const used=new Set(PLANTS.flatMap(id=>state.plants[id].lanes.flatMap(l=>l.machines.map(m=>m.kind))));const cost=masteryCost(state);const open=state.produced>=MASTERY_AT;
 return `<section class="panel masteries"><span class="eyebrow">MAÎTRISES</span><h3>Doubler ce que vous utilisez</h3><p class="muted">${open?`Chaque niveau multiplie par ${MASTERY_FACTOR} l’effet d’une famille, là où elle agit réellement. Tous les niveaux partagent la même échelle de prix : prochain niveau ${fmt(cost)} ⬡.`:`Disponibles à ${fmt(MASTERY_AT)} composants cumulés.`}</p>${open?`<div class="mastery-list">${MASTERY_FAMILIES.filter(k=>unlocked(state,k)).map(k=>`<div class="mastery ${used.has(k)?'used':''}"><span class="module-icon">${moduleSymbol(k)}</span><div><strong>${MODULES[k].name}</strong><small>Niveau ${masteryLevel(state,k)} · effet ×${fmt(MASTERY_FACTOR**masteryLevel(state,k))}${used.has(k)?'':' · non utilisée'}</small></div>${btn('mastery','＋',`data-kind="${k}" aria-label="Maîtrise : ${MODULES[k].name}"`,state.plants.A.stock.components<cost)}</div>`).join('')}</div>`:''}</section>`;}
function upgrades(){const p=state.plants[plant];return `<section class="panel upgrades"><span class="eyebrow">INFRASTRUCTURE</span><h3>Donner de l’ampleur à vos idées</h3><p class="muted">Augmenter l’alimentation change le goulot. Les procédés restent les vôtres.</p>${(plant==='A'?['oreLevel','energyLevel']:['energyLevel']).filter(()=>plantUnlocked(state,plant)).map(k=>{const key=k as 'oreLevel'|'energyLevel';return `<div class="upgrade"><div><strong>${key==='oreLevel'?'Extraction':'Générateurs'} ×2</strong><small>Niveau ${p[key]} / ${UPGRADE_MAX} · ${fmt((key==='oreLevel'?12:BASE_ENERGY[plant])*2**p[key])} → ${fmt((key==='oreLevel'?12:BASE_ENERGY[plant])*2**(p[key]+1))}/s</small></div>${btn('upgrade',`${fmt(upgradeCost(p[key]))} ⬡`,`data-type="${key}"`,p[key]>=UPGRADE_MAX||state.plants.A.stock.components<upgradeCost(p[key]))}</div><p class="upgrade-advice">${t(supplyHint(state,plant,key))}</p>`;}).join('')}<div class="rule-note">Capacités annoncées : réserves 10²¹, qualité ×10¹², lot ≤ ${packetMax(state)}, tampon 800 par machine. Pas de perte par destruction.</div></section>`;}
function cooperation(){const labels=['Résidus Fonderie → Serre','Catalyseurs Serre → Fonderie','Catalyseurs Serre → Forge','Plasma Forge → Fonderie'];return `<section class="panel"><span class="eyebrow">TROIS INSTALLATIONS / UN TRIANGLE</span><h2>La matière circule. La puissance revient.</h2>${plantUnlocked(state,'B')?`<div class="cooperation-flow triangle"><div><span class="plant-symbol">⬡</span><h3>Fonderie</h3><p>Matière → composants<br>+ chaleur résiduelle</p></div><div><span class="plant-symbol">✧</span><h3>Serre catalytique</h3><p>Résidus → catalyseurs</p></div><div class="${plantUnlocked(state,'C')?'':'locked'}"><span class="plant-symbol">✺</span><h3>Forge à plasma</h3><p>${plantUnlocked(state,'C')?'Catalyseurs → plasma':`À ${fmt(plantUnlockAt(state,'C'))} composants cumulés`}</p></div></div><div class="transfer-list">${state.transfers.map((tr,i)=>(i<2||plantUnlocked(state,'C'))?`<div class="transfer-row"><div><strong>${labels[i]}</strong><small>${fmt(tr.rate*(progressOf(state).patents.includes('transfer')?4:1))}/s · ${fmt(tr.moved)} transférés au total</small></div>${btn('transfer',tr.enabled?'Suspendre':'Activer',`data-index="${i}"`)}</div>`:'').join('')}</div><p class="muted">Les transferts sont automatiques, limités par le stock disponible et la capacité d’accueil.</p><label class="check"><input type="checkbox" data-catalyst ${state.plants.A.catalystOn?'checked':''}> La Fonderie consomme 1 catalyseur par lot pour multiplier la sortie par ${progressOf(state).patents.includes('catalysis')?6:4}.</label>${plantUnlocked(state,'C')?`<label class="check"><input type="checkbox" data-plasma ${state.plants.A.plasmaOn!==false?'checked':''}> La Fonderie consomme 1 plasma par lot pour multiplier la sortie par 10.</label>`:''}`:`<div class="empty">Une deuxième installation ouvrira à 1 000 composants cumulés.<p>Elle valorisera les résidus et renverra un activateur à la Fonderie.</p><progress value="${state.produced}" max="1000"></progress></div>`}</section>`;}
function library(){return `<div class="section-head"><div><span class="eyebrow">VOS OUTILS, VOS NOMS</span><h2>Bibliothèque d’inventions</h2></div></div><p class="muted">Encapsuler conserve exactement les machines et cycles de la ligne active. Une nouvelle instance paie toutes ses machines et démarre avec des tampons vides : aucun stock n’est copié. Une seule couche d’encapsulation.</p><p class="muted tiny">Les nouvelles instances laissent les branches externes à reconnecter. Les configurations conservent les connexions entre leurs lignes.</p><div class="share-bar">${btn('import-code','Importer un code d’invention','class="subtle"')}<span class="muted tiny">Un code contient le plan, jamais les stocks ni les cycles.</span></div><div class="library-grid">${state.library.length?state.library.map((b,i)=>`<article class="panel blueprint"><span class="eyebrow">▣ COMPOSANT PERSONNEL</span><h3><span data-user-text>${esc(b.name)}</span></h3><div class="blueprint-chain">${b.machines.map(m=>MODULES[m.kind].icon).join(' → ')}</div><p>${b.machines.length} machines · coût de base ${fmt(b.machines.reduce((n,m)=>n+MODULES[m.kind].cost,0))} composants</p>${btn('deploy','Construire ici',`data-index="${i}" class="primary"`,!plantUnlocked(state,plant))}${btn('insert-blueprint','Insérer dans la ligne choisie',`data-index="${i}"`,!lane())}${btn('share-blueprint','Copier le code',`data-index="${i}" class="subtle"`)}${cloudReady()?btn('publish-blueprint','Publier dans la galerie',`data-index="${i}" class="subtle"`):''}${btn('delete-blueprint','Supprimer le plan',`data-index="${i}" class="subtle"`)}</article>`).join(''):'<div class="panel empty">Votre première invention vous attend.<p>L’encapsulation s’ouvre à 1 000 composants cumulés.</p></div>'}</div>${galleryPanel()}<section class="panel"><h3>Configurations de l’installation</h3><p class="muted">Restaurer remplace les lignes de l’installation concernée et rend leurs coûts et matières internes. Les nouveaux cycles démarrent à zéro ; les plans ne sont pas des instantanés de production.</p>${state.configurations.length?state.configurations.map((c,i)=>`<div class="config-row"><div><strong><span data-user-text>${esc(c.name)}</span></strong><small>${c.plant==='A'?'Fonderie':'Serre'} · ${c.lanes.length} lignes</small></div><div>${btn('load-config','Restaurer',`data-index="${i}"`)}${btn('delete-config','✕',`data-index="${i}" aria-label="Supprimer cette configuration"`)}</div></div>`).join(''):'<p class="muted">Enregistrez une configuration depuis l’atelier, dès maintenant.</p>'}</section>`;}
function experiments(){return `${puzzle?'':contractsPanel(state)}${puzzle?'':puzzlesPanel()}<div class="section-head"><div><span class="eyebrow">PROTOCOLES / AUCUNE RECETTE IMPOSÉE</span><h2>Carnet d’expériences</h2></div></div><div class="experiment-grid">${EXPERIMENTS.map((e,i)=>`<article class="panel experiment"><span class="eyebrow">EXPÉRIENCE ${String(i+1).padStart(2,'0')} ${state.claimed.includes(e.id)?'· VALIDÉE':''}</span><h3>${e.name}</h3><p>${e.description}</p><progress max="1" value="${Math.min(1,e.progress(state))}"></progress><div class="experiment-bottom"><span>Dotation : ${fmt(e.reward)} ⬡</span>${btn('claim',state.claimed.includes(e.id)?'Validée':e.test(state)?'Valider':'En cours',`data-id="${e.id}"`,state.claimed.includes(e.id)||!e.test(state))}</div></article>`).join('')}</div>${challengeCards(state)}`;}
function overview(){return `<div class="overview-grid"><section class="panel"><span class="eyebrow">MESURES / SECONDES DE SIMULATION</span><h2>Un laboratoire qui s’explique</h2>${chart()}<div class="metrics"><div><strong>${fmt(measuredRate(state).rate)}/s</strong><small>Moyenne sur ${fmt(measuredRate(state).duration)} s</small></div><div><strong>${fmt(state.peak)}</strong><small>Plus grand lot produit · pas un débit</small></div><div><strong>${fmt(state.recovered)}</strong><small>Matières récupérées</small></div></div><p class="muted">La moyenne glissante inclut les changements de configuration. Un cycle long demande au moins une minute d’observation. Aucune comparaison automatique avec une référence différente.</p></section>${upgrades()}</div>${cooperation()}<section class="panel"><h3>Journal de l’installation</h3>${state.log.map(l=>`<div class="log-row"><time>${time(l.tick)}</time><span>${esc(l.text)}</span></div>`).join('')}</section>`;}
function showcase(){
 const rate=measuredRate(state);
 return `<div class="showcase-view"><header><div><span class="eyebrow">RÉSONANCE INDUSTRIELLE · VITRINE</span><strong data-live="produced">${fmt(state.produced)}</strong><small>composants cumulés</small></div><div><strong data-live="rate">${fmt(rate.rate)}</strong><small>composants / s</small></div>${btn('showcase-exit','✕','aria-label="Quitter la vitrine"')}</header>${PLANTS.filter(id=>plantUnlocked(state,id)&&state.plants[id].lanes.length).map(id=>`<section><h2>${PLANT_NAMES[id]}</h2>${networkOverview(state,id,0)}</section>`).join('')}</div>`;}
function render(){
 if(!puzzle&&rememberGuideProgress(state,preferences))savePreferences();
 checkPuzzle();
 if(view==='showcase'){document.documentElement.classList.add('showcase-mode');$('#app').innerHTML=showcase();translateDOM($('#app'));return;}
 document.documentElement.classList.remove('showcase-mode');
 document.documentElement.lang=preferences.language;document.title=preferences.language==='en'?'Resonance · Industrial laboratory':'Résonance · Laboratoire industriel';
 const scroll=$('.node-strip')?.scrollLeft??0;const kept=['.inspector','.resources','.network-frame','.milestone-track','.lane-tabs'].map(q=>[q,document.querySelector(q)?.scrollLeft??0,document.querySelector(q)?.scrollTop??0] as const);const focus=document.activeElement as HTMLElement|null;const focusData=focus?{...focus.dataset}:null;
 const p=state.plants[plant];if(!p.lanes.some(l=>l.id===selectedLane)){selectedLane=p.lanes[0]?.id??0;selectedMachine=0;}
 const rate=measuredRate(state);const blocking=diagnosis(state,plant);const blockingLane=p.lanes.find(l=>l.machines.some(m=>m.id===blocking?.id));
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" aria-label="Résonance"><span class="brand-mark">R<span>↗</span></span><span>RÉSONANCE<small>INDUSTRIELLE</small></span></a><div class="sidebar-section">LABORATOIRE PERSONNEL</div><nav>${[['atelier','⌘','Atelier'],['overview','▥','Vue générale'],['library','▣','Inventions'],['experiments','⌬','Expériences'],['notebook','✦','Carnet'],['bench','⌁','Banc d’essai'],['guide','?','Premiers pas']].map(([v,icon,label])=>btn('nav',`<span>${icon}</span>${label}${v==='experiments'&&EXPERIMENTS.some(e=>e.test(state)&&!state.claimed.includes(e.id))?'<i class="notification"></i>':''}`,`data-view="${v}" class="${view===v?'active':''}"`)).join('')}</nav><div class="sidebar-section">INSTALLATIONS</div><div class="plant-nav">${btn('plant','<span>01</span><div>Fonderie<small>Composants & récupération</small></div>',`data-plant="A" class="${plant==='A'?'active':''}"`)}${btn('plant',`<span>02</span><div>Serre catalytique<small>${plantUnlocked(state,'B')?'Valorisation des résidus':'À 1 000 composants cumulés'}</small></div>`,`data-plant="B" class="${plant==='B'?'active':''}"`,!plantUnlocked(state,'B'))}${btn('plant',`<span>03</span><div>Forge à plasma<small>${plantUnlocked(state,'C')?'Catalyseurs → plasma':`À ${fmt(plantUnlockAt(state,'C'))} composants cumulés`}</small></div>`,`data-plant="C" class="${plant==='C'?'active':''}"`,!plantUnlocked(state,'C'))}</div><div class="sidebar-bottom"><div class="local-status"><i class="dot"></i> LOCAL · SANS CONNEXION</div><small>${storageBlocked?'Sauvegarde automatique suspendue':`Sauvegarde : ${lastSave}`}</small><div class="save-actions">${btn('save','Sauver')}${btn('export','Exporter')}${btn('import','Importer')}</div>${btn('help','Règles & fonctionnement','class="help-button"')}${btn('reset','Nouvelle partie','class="reset-button"')}<small class="version">PROTOTYPE 0.6 / AUCUN GAIN HORS LIGNE</small></div></aside><main><header class="topbar"><div><span class="muted">Centre de recherche</span><span class="crumb">/</span>${PLANT_NAMES[plant]}${variantOf(state)!=='standard'?` <span class="variant-pill">${VARIANT_NAMES[variantOf(state)]}</span>`:''}</div><div><span class="mobile-hud" aria-label="Production"><span><strong data-live="rate">${fmt(rate.rate)}</strong><small>/s</small></span><span><i>⬡</i><strong data-live="stock" data-resource="components">${fmt(state.plants[plant].stock.components)}</strong></span></span><label class="language-picker"><span>Langue</span><select data-language aria-label="Choisir la langue du jeu"><option data-user-text value="fr" ${preferences.language==='fr'?'selected':''}>Français</option><option data-user-text value="en" ${preferences.language==='en'?'selected':''}>English</option></select></label><span class="session-time">◷ ${time(state.tick)}</span><span class="engine-status ${state.paused?'paused':''}"><i class="dot"></i>${state.fault?'Diagnostic':state.paused?'En pause':'Simulation active'}</span>${btn('sound',effects.sound?'♪ Son actif':'♪ Son coupé',`class="sound-button ${effects.sound?'on':''}" aria-pressed="${effects.sound}"`)}${plantUnlocked(state,'B')?`<span class="plant-switch">${btn('plant','⬡','data-plant="A" aria-label="Fonderie" class="'+(plant==='A'?'active':'')+'"')}${btn('plant','✧','data-plant="B" aria-label="Serre catalytique" class="'+(plant==='B'?'active':'')+'"')}${plantUnlocked(state,'C')?btn('plant','✺','data-plant="C" aria-label="Forge à plasma" class="'+(plant==='C'?'active':'')+'"'):''}</span>`:''}${btn('pause',state.paused?'▶ Reprendre':'Ⅱ Pause','class="pause-button"')}${btn('showcase','⛶','class="showcase-button" aria-label="Mode vitrine" title="Mode vitrine"')}${btn('menu','☰','class="menu-button" aria-label="Menu"')}</div></header><div class="content"><section class="hero"><div><span class="eyebrow">L’INVENTION EST UNE CHAÎNE DE DÉCISIONS.</span><h1>${view==='atelier'?'La puissance est dans les liens.':view==='library'?'Ne perdez pas vos bonnes idées.':view==='experiments'?'Faire mieux. Comprendre pourquoi.':'Observer les effets de vos idées.'}</h1><p>Combinez des règles simples. Construisez des effets qui ne le sont plus.</p></div><div class="live-yield"><span class="eyebrow">PRODUCTION MOYENNE</span><button data-action="rate"><strong data-live="rate">${fmt(rate.rate)}</strong><span>composants / s ↗</span></button><small>${rate.duration<60?'Mesure en cours':'Fenêtre glissante'} · ${fmt(rate.duration)} s</small></div></section>${puzzle?puzzleBanner():''}${state.fault?`<div class="warning">Moteur arrêté : ${esc(state.fault)}. Exportez votre partie pour diagnostic.</div>`:''}${progressDeck(state)}${view==='atelier'?onboardingPanel(state,preferences):''}${resources()}${view!=='experiments'?challengeNotice(state):''}${view==='atelier'?`${changePanel(state,observation)}<div class="diagnosis"><span>◉ OBSERVATION</span>${blocking?esc(t(blocking.kind==='router'&&(!blocking.routing||!state.plants[plant].lanes.some(l=>l.id===blocking.routing!.target))?'Choisir une ligne de destination':blocking.status))+' · '+t(MODULES[blocking.kind].name):'Les entrées circulent. Explorez les modules pour changer leur comportement.'}${blocking?btn('network-module','Examiner le frein',`data-lane="${blockingLane!.id}" data-id="${blocking.id}"`):''}</div><div class="atelier-grid"><div>${workshop()}${catalog()}</div><div class="right-column">${inspector()}${masteries()}${upgrades()}</div></div>`:view==='library'?library():view==='experiments'?experiments():view==='notebook'?notebookPage(state,meta,ghostBase):view==='guide'?guidePage()+puzzlesPanel():view==='bench'?benchPage(benchReference,benchResult,benchDuration,plant):overview()}<footer><span>Résonance industrielle · un atelier pour vos idées</span><span>Déterministe · Réversible · Local</span></footer></div></main>`;
 if(view==='atelier'&&!preferences.guide.hidden&&$('.inspector'))$('.inspector').insertAdjacentHTML('beforeend',btn('guide-return','Revenir au guide','class="wide subtle"'));
 translateDOM($('#app'));
 const strip=$('.node-strip');if(strip)strip.scrollLeft=scroll;for(const [q,left,top] of kept){const el=document.querySelector(q);if(el){el.scrollLeft=left;el.scrollTop=top;}}
 if(focusData?.action&&!$('#dialog').hasAttribute('open')){const candidate=[...document.querySelectorAll<HTMLElement>('[data-action]')].find(x=>Object.entries(focusData).every(([k,v])=>x.dataset[k]===v));candidate?.focus({preventScroll:true});}
}
document.addEventListener('click',e=>{
 const b=(e.target as Element).closest<HTMLElement>('[data-action]');if(!b||b.hasAttribute('disabled'))return;
 const a=b.dataset.action!,d=b.dataset;let result=true;
 if(b.closest('.mobile-menu'))$<HTMLDialogElement>('#dialog').close();
 const edits=['add-module','add-source-line','add-branch-line','connect','upgrade','remove-module','move','remove-lane','deploy','load-config','transfer','router-source'];
 const before=edits.includes(a)?clone(state):null;
 if(a==='change-dismiss'){observation=null;render();return;}
 if(a==='change-compare'&&observation){benchReference=clone(observation.before);benchResult=compareLayouts(benchReference,state,observation.plant,benchDuration);plant=observation.plant;view='bench';render();return;}
 if(a==='challenge-start'){startChallenge(state,d.id!);save();render();return;}
 if(a==='challenge-stop'){if(state.challenges)state.challenges.active=null;save();render();return;}
 if(a==='lesson-bench'){benchReference=clone(state);benchResult=null;view='bench';render();return;}
 if(a==='lesson-branch'){plant='A';view='atelier';popup('Quel rôle pour la nouvelle ligne ?',lineChoices());return;}
 if(a==='lesson-cooperation'){view='overview';render();return;}
 if(a==='close'){$<HTMLDialogElement>('#dialog').close();render();return;}
 if(a==='guide-intake'||a==='guide-press'){
   const kind=a==='guide-intake'?'intake':'press';plant='A';view='atelier';const target=state.plants.A.lanes.find(l=>l.machines.some(m=>m.kind===kind));
   if(target){selectedLane=target.id;target.capsule=false;selectedMachine=target.machines.find(m=>m.kind===kind)!.id;preferences.guide[kind==='intake'?'intake':'press']=true;savePreferences();}
   render();$('.inspector')?.scrollIntoView({behavior:'smooth',block:'center'});return;
 }
 if(a==='guide-modules'){view='atelier';render();$('.catalog')?.scrollIntoView({behavior:'smooth',block:'center'});return;}
 if(a==='guide-return'){$('#onboarding')?.scrollIntoView({behavior:'smooth',block:'center'});return;}
 if(a==='guide-dismiss'){preferences.guide.hidden=true;savePreferences();render();toast('Guide masqué. Retrouvez-le dans « Premiers pas ».');return;}
 if(a==='guide-restart'){preferences.guide=defaultPreferences().guide;preferences.lessons=defaultPreferences().lessons;savePreferences();view='atelier';render();$('#onboarding')?.scrollIntoView({behavior:'smooth',block:'center'});return;}
 if(a==='guide-resume'){preferences.guide.hidden=false;savePreferences();view='atelier';render();return;}
 if(a==='guide-back'){view='atelier';render();return;}
 if(a==='guide-experiments'){view='experiments';render();return;}
 if(a==='help'){view='guide';render();return;}
 if(a==='bench-record'){
   benchReference=clone(state);benchResult=null;
   try{localStorage.setItem(BENCH_KEY,serialize(benchReference));}catch{}
   view='bench';render();toast('Référence mémorisée. Modifiez votre atelier avant de comparer.');return;
 }
 if(a==='bench-run'){
   if(benchReference)try{benchResult=compareLayouts(benchReference,state,plant,benchDuration);}catch{toast('Banc d’essai indisponible');}
   view='bench';render();return;
 }
 if(a==='router-source'){const r=findMachine()?.routing;const target=state.plants[plant].lanes.find(l=>l.id===r?.target);if(target)target.machines[0].connected=!target.machines[0].connected;if(before)observation=observeChange(before,plant,'Alimentation de destination modifiée');updateChallenge(state);render();return;}
 if(a==='showcase'){view='showcase';render();document.documentElement.requestFullscreen?.().catch(()=>{});return;}
 if(a==='showcase-exit'){view='atelier';if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});render();return;}
 if(a==='puzzle-start'){enterPuzzle(d.id!);render();window.scrollTo({top:0});return;}
 if(a==='puzzle-exit'){$<HTMLDialogElement>('#dialog').close();exitPuzzle();render();return;}
 if(a==='puzzle-next'){$<HTMLDialogElement>('#dialog').close();exitPuzzle();enterPuzzle(d.id!);render();window.scrollTo({top:0});return;}
 if(a==='puzzle-reset'){if(puzzle){state=puzzleState(puzzle.def);puzzle.won=false;puzzle.score=undefined;selectedLane=state.plants.A.lanes[0].id;selectedMachine=0;observation=null;}render();return;}
 if(a==='daily-measure'){if(puzzle?.daily){const score=measureDaily(state);puzzle.score=score;const key=puzzle.def.id.slice(6);const record=meta.daily[key]===undefined||score>meta.daily[key];if(record){meta.daily[key]=score;saveMeta();}if(cloudReady())submitScore(key,score).then(refreshBoard).catch(()=>{});popup('Mesure du puzzle du jour',`<p>Votre atelier, redémarré à vide : <strong>${fmt(score)} composants/s</strong> sur 120 s après 60 s de chauffe.</p><p>${record?'Nouveau record du jour.':`Record du jour : ${fmt(meta.daily[key])}/s.`}</p>${btn('close','Continuer','class="primary"')}`);}return;}
 if(a==='gallery-refresh'){gallery=null;refreshGallery();render();return;}
 if(a==='publish-blueprint'){const bp=state.library[Number(d.index)];if(bp){const rate=measureBlueprint(bp);publishInvention({name:bp.name,code:encodeBlueprint(bp),rate}).then(()=>{toast(`Invention publiée · ${fmt(rate)}/s mesurés seule.`);refreshGallery();}).catch(e=>toast((e as Error).message));}return;}
 if(a==='gallery-vote'){const g=gallery?.[Number(d.index)];if(g)toggleVote(`${g.owner}:${g.at}`).then(refreshGallery).catch(()=>toast('Vote impossible pour le moment.'));return;}
 if(a==='gallery-import'){const g=gallery?.[Number(d.index)];if(g)try{const bp=decodeBlueprint(g.code);if(state.library.length>=30)throw Error('Bibliothèque pleine (30 plans).');state.library.push(bp);save();toast('Invention ajoutée à la bibliothèque.');render();}catch(e){toast((e as Error).message);}return;}
 if(a==='cloud-save'){$<HTMLDialogElement>('#dialog').close();const real=puzzle?puzzle.main:state;cloudSave(serialize(real),real.produced).then(()=>toast('Partie sauvegardée en ligne.')).catch(e=>toast((e as Error).message));return;}
 if(a==='cloud-load'){$<HTMLDialogElement>('#dialog').close();cloudLoad().then(r=>{if(!r){toast('Aucune sauvegarde en ligne.');return;}const candidate=deserialize(r.json);popup('Charger la sauvegarde en ligne ?',`<p>Sauvegarde du ${esc(r.at.slice(0,16).replace('T',' '))} : ${fmt(candidate.produced)} composants cumulés. Votre partie actuelle restera disponible comme sauvegarde précédente.</p>${btn('confirm-cloud-load','Charger cette partie','class="primary"')}`);pendingCloud=candidate;}).catch(e=>toast((e as Error).message));return;}
 if(a==='confirm-cloud-load'){if(pendingCloud){try{if(!storageBlocked)persist(localStorage,state);}catch{}state=pendingCloud;pendingCloud=null;observation=null;plant='A';selectedLane=state.plants.A.lanes[0]?.id??0;selectedMachine=0;$<HTMLDialogElement>('#dialog').close();save();toast('Partie en ligne chargée. Aucun temps hors ligne ajouté.');}render();return;}
 if(a==='mastery'){const before2=clone(state);if(buyMastery(state,d.kind as Kind)){observation=observeChange(before2,plant,'Maîtrise acquise');toast(`Maîtrise : ${MODULES[d.kind as Kind].name} niveau ${masteryLevel(state,d.kind as Kind)}.`);}else toast('Composants insuffisants pour ce niveau.');render();return;}
 if(a==='contract-accept'){if(!acceptContract(state,Number(d.index)))toast('Contrat indisponible.');save();render();return;}
 if(a==='contract-abandon'){abandonContract(state);save();render();return;}
 if(a==='patent'){if(buyPatent(state,d.id!))toast('Brevet acquis : la règle s’applique immédiatement.');else toast('Brevets insuffisants.');save();render();return;}
 if(a==='theme'){meta.theme=d.theme!;saveMeta();applyDisplay();render();return;}
 if(a==='display'){const k=d.key!;if(k==='zoom')meta.zoom=[.85,1,1.15,1.3][([.85,1,1.15,1.3].indexOf(meta.zoom)+1)%4];if(k==='contrast')meta.contrast=!meta.contrast;if(k==='music'){meta.music=!meta.music;if(meta.music)enableMusic(effects);}saveMeta();applyDisplay();$<HTMLDialogElement>('#dialog').close();render();return;}
 if(a==='refound'){popup('Refonder le laboratoire ?',`<p>La production, les stocks et les machines repartent de zéro. Vous gardez inventions, configurations, découvertes, badges et brevets.</p><p><strong>Mémoire : ×${fmt(Math.max(progressOf(state).legacy,1.25**(state.discoveries?.length??0)))}</strong> sur chaque presse de Fonderie.</p>${variantChoices('confirm-refound')}`);return;}
 if(a==='confirm-refound'){const next=refound(state,(d.variant as Variant)??variantOf(state));if(next){if(!storageBlocked)try{persist(localStorage,state);}catch{}state=next;observation=null;plant='A';selectedLane=state.plants.A.lanes[0].id;selectedMachine=0;view='atelier';$<HTMLDialogElement>('#dialog').close();save();toast('Laboratoire refondé. Votre mémoire vous accompagne.');}render();return;}
 if(a==='estimate'){const kind=d.kind as Kind;const result=estimateInsertion(kind);if(result===null){toast('Estimation impossible ici.');return;}popup(`Estimer : ${MODULES[kind].name}`,`<p>Simulation de 90 s à partir de l’état actuel, avec et sans ce module sur la ligne choisie. Rien n’est acheté ni produit dans votre partie.</p><div class="change-metrics"><div><small>Sans le module</small><strong>${fmt(result.without)}/s</strong></div><div><small>Avec le module</small><strong>${fmt(result.with)}/s</strong></div></div><p><strong>${result.without>0?`≈ ×${fmt(result.with/result.without)}`:'Comparaison impossible : aucune production sans le module.'}</strong></p><p class="tiny muted">Estimation courte : les files déjà présentes et les cycles longs peuvent retarder l’effet réel. Le banc d’essai donne une mesure stabilisée.</p>${btn('add-module',`Ajouter · ${fmt(costOf(state,kind))} ⬡`,`data-kind="${kind}" class="primary"`)}`);return;}
 if(a==='insert-blueprint'){const before2=clone(state);if(insertBlueprint(state,plant,selectedLane,Number(d.index))){observation=observeChange(before2,plant,'Invention insérée');view='atelier';toast('Modules de l’invention insérés dans la ligne.');}else toast('Insertion impossible : place, budget ou déblocages.');render();return;}
 if(a==='share-blueprint'){const code=encodeBlueprint(state.library[Number(d.index)]);popup('Code de l’invention',`<p>Copiez ce code pour partager votre plan. Il ne contient ni stocks ni cycles.</p><textarea class="code-box" readonly rows="4">${esc(code)}</textarea>${btn('copy-code','Copier','class="primary"')}`);return;}
 if(a==='copy-code'){const box=$<HTMLTextAreaElement>('#dialog .code-box');box.select();navigator.clipboard?.writeText(box.value).then(()=>toast('Code copié.'),()=>toast('Sélectionnez le code puis copiez-le.'));return;}
 if(a==='import-code'){popup('Importer un code d’invention',`<p>Collez un code commençant par RI1-. Le plan rejoint votre bibliothèque ; construisez-le ensuite en payant ses machines.</p><textarea class="code-box" rows="4" placeholder="RI1-…"></textarea>${btn('confirm-code','Ajouter à la bibliothèque','class="primary"')}`);return;}
 if(a==='confirm-code'){try{const bp=decodeBlueprint($<HTMLTextAreaElement>('#dialog .code-box').value);if(state.library.length>=30)throw Error('Bibliothèque pleine (30 plans).');state.library.push(bp);$<HTMLDialogElement>('#dialog').close();save();view='library';render();toast('Invention ajoutée à la bibliothèque.');}catch(e){toast((e as Error).message);}return;}
 if(a==='network-module'){selectedLane=Number(d.lane);selectedMachine=Number(d.id);const l=lane();if(l)l.capsule=false;render();$('.inspector')?.scrollIntoView({behavior:'smooth',block:'center'});return;}
 if(a==='nav'){view=d.view!;selectedMachine=0;if(cloudReady()&&view==='library'&&gallery===null)refreshGallery();if(cloudReady()&&view==='experiments'&&board===null)refreshBoard();}
 else if(a==='plant'){benchResult=null;plant=d.plant as PlantId;selectedLane=state.plants[plant].lanes[0]?.id??0;selectedMachine=0;}
 else if(a==='pause'){state.paused=!state.paused;save();}
 else if(a==='sound'){effects.sound=!effects.sound;writeEffects(localStorage,effects);enableSound(effects);}
 else if(a==='deselect'){selectedMachine=0;}
 else if(a==='menu'){popup('Menu',`<div class="mobile-menu"><label class="language-picker"><span>Langue</span><select data-language aria-label="Choisir la langue du jeu"><option data-user-text value="fr" ${preferences.language==='fr'?'selected':''}>Français</option><option data-user-text value="en" ${preferences.language==='en'?'selected':''}>English</option></select></label>${btn('sound',effects.sound?'♪ Son actif':'♪ Son coupé','class="wide"')}<div class="menu-row">${btn('save','Sauver')}${btn('export','Exporter')}${btn('import','Importer')}</div>${cloudReady()?`<div class="menu-row">${btn('cloud-save','☁ Sauver en ligne')}${btn('cloud-load','☁ Charger')}</div>`:''}<div class="menu-row">${btn('display',`Texte ×${meta.zoom}`,'data-key="zoom"')}${btn('display',meta.contrast?'Contraste fort ✓':'Contraste fort','data-key="contrast"')}${btn('display',meta.music?'Musique ✓':'Musique','data-key="music"')}</div>${btn('showcase','⛶ Mode vitrine','class="wide subtle"')}${btn('help','Règles & fonctionnement','class="wide subtle"')}${btn('reset','Nouvelle partie','class="wide danger-text"')}<small class="muted">${storageBlocked?'Sauvegarde automatique suspendue':`Sauvegarde : ${lastSave}`}</small></div>`);return;}
 else if(a==='select-lane'){selectedLane=Number(d.id);selectedMachine=0;}
 else if(a==='select-module'){selectedMachine=Number(d.id);const kind=findMachine()?.kind;if(kind==='intake')preferences.guide.intake=true;if(kind==='press')preferences.guide.press=true;savePreferences();}
 else if(a==='add-lane'){popup('Quel rôle pour la nouvelle ligne ?',lineChoices());return;}
 else if(a==='add-source-line'||a==='add-branch-line'){result=addLane(state,plant,undefined,a==='add-branch-line'?'branch':'source');if(result){selectedLane=state.plants[plant].lanes.at(-1)!.id;selectedMachine=0;$<HTMLDialogElement>('#dialog').close();view='atelier';}}
 else if(a==='add-module'){result=insertModule(state,plant,selectedLane,d.kind as Kind);const dlg=$<HTMLDialogElement>('#dialog');if(dlg.open)dlg.close();}
 else if(a==='module-info'){const def=MODULES[d.kind as Kind];popup(def.name,`<p>${def.description}</p><p class="muted">Coût de construction actuel : ${fmt(costOf(state,d.kind as Kind))} composants (+15 % par exemplaire). Tampon : 800 matières. Qualité maximale : ×10¹².</p>`);return;}
 else if(a==='connect'){const m=lane()?.machines.find(m=>m.id===Number(d.id));if(m)m.connected=!m.connected;}
 else if(a==='upgrade')result=upgrade(state,plant,d.type as 'oreLevel'|'energyLevel');
 else if(a==='remove-module')result=removeModule(state,plant,selectedLane,selectedMachine);
 else if(a==='move')result=moveModule(state,plant,selectedLane,selectedMachine,Number(d.dir));
 else if(a==='encapsulate'){ask('Donner un nom à cette invention','capsule',lane()?.name);return;}
 else if(a==='save-config'){ask('Enregistrer la configuration','config');return;}
 else if(a==='expand'){const l=lane();if(l)l.capsule=false;}
 else if(a==='remove-lane'){result=removeLane(state,plant,selectedLane);}
 else if(a==='deploy'){result=addLane(state,plant,state.library[Number(d.index)]);if(result){view='atelier';selectedLane=state.plants[plant].lanes.at(-1)!.id;}}
 else if(a==='delete-blueprint')state.library.splice(Number(d.index),1);
 else if(a==='delete-config')state.configurations.splice(Number(d.index),1);
 else if(a==='load-config'){result=loadConfiguration(state,Number(d.index));if(result){plant=state.configurations[Number(d.index)].plant;view='atelier';}}
 else if(a==='transfer')state.transfers[Number(d.index)].enabled=!state.transfers[Number(d.index)].enabled;
 else if(a==='claim')result=claim(state,d.id!);
 else if(a==='save'){if(save())toast('Partie sauvegardée sur cet ordinateur.');}
 else if(a==='export'){try{const json=storageBlocked?(localStorage.getItem(SAVE_KEY)??serialize(state)):serialize(state);const filename=`resonance-${new Date().toISOString().slice(0,10)}.json`;if(hostDownloads){hostDownloads.save({filename,data:json}).catch((e:{code?:string})=>{if(e?.code!=='declined')toast('Export impossible ici : copiez votre partie depuis l’ordinateur.');});}else{const url=URL.createObjectURL(new Blob([json],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}}catch(e){toast((e as Error).message);}}
 else if(a==='import'){$<HTMLInputElement>('#import-file').click();return;}
 else if(a==='reset'){popup('Recommencer une partie ?',`<p>La partie courante sera remplacée. Exportez-la pour conserver vos inventions.</p>${variantChoices('confirm-reset')}`);return;}
 else if(a==='confirm-reset'){try{if(!storageBlocked)persist(localStorage,state);state=createState((d.variant as Variant)??'standard');observation=null;benchReference=null;benchResult=null;try{localStorage.removeItem(BENCH_KEY);}catch{}preferences.guide=defaultPreferences().guide;preferences.lessons=defaultPreferences().lessons;savePreferences();storageBlocked=false;save();selectedLane=state.plants.A.lanes[0].id;plant='A';view='atelier';$<HTMLDialogElement>('#dialog').close();}catch(e){toast((e as Error).message);}}
 else if(a==='rate'){if(preferences.guide.added)preferences.guide.rate=true;savePreferences();popup('Débit moyen et pic de production',`<p><strong>${fmt(rateValue())} composants/s</strong> sur ${fmt(measuredRate(state).duration)} secondes de simulation.</p>${chart()}<p>Chaque seconde, le moteur mesure la production réelle des presses. La moyenne porte sur les 60 dernières secondes disponibles, y compris les changements de configuration. Les dotations d’expériences et remboursements sont exclus.</p><p>Plus grand cycle : ${fmt(state.peak)} composants. Ce pic ne constitue pas un débit soutenu.</p><p class="muted">Formule de la Fonderie : matières ÷ 10 × qualité × (8 si lot ≥ 80, sinon 1) × (4 si 1 catalyseur consommé, sinon 1) × (10 si 1 plasma consommé, sinon 1) × mémoire de refondation. Chaque presse ne traite qu’un lot par seconde.</p>`);return;}
 else if(a==='resource'){const r=d.resource as Resource;popup(RESOURCE_NAMES[r],`<p>Réserve locale : <strong>${fmt(state.plants[plant].stock[r])}</strong> / 10²¹.</p><p>${r==='ore'?'Extraction de base : 12/s, multipliée par 2 à chaque niveau. Les injecteurs prélèvent 6 ou 12 matières par cycle de 0,5 s, selon leur réglage. Le récupérateur peut restituer 80 % après pressage.':r==='energy'?'Génération de base : 8/s × 2 par niveau. Chaque presse consomme 0,5 énergie/matière à la Fonderie, 0,25 à la Serre. Les charges et récupérateurs ont leurs coûts propres.':r==='components'?'Produit par les presses de la Fonderie. Sert de budget commun de construction et d’amélioration. Les déblocages utilisent la production cumulée, jamais le stock restant.':r==='residue'?'Chaque pressage de la Fonderie crée 0,5 résidu/matière sous forme de chaleur exploitable. La Serre les reçoit à 20/s maximum.': r==='catalyst'?'La Serre transforme 20 résidus en 1 catalyseur, multiplié par la qualité du lot. Retour vers la Fonderie : 4/s maximum, et 20/s vers la Forge. Une presse de Fonderie peut en consommer 1 pour une sortie ×4.':'La Forge transforme 40 catalyseurs en 1 plasma, multiplié par la qualité du lot. Retour vers la Fonderie : 4/s maximum. Une presse de Fonderie peut en consommer 1 pour une sortie ×10.'}</p><p class="muted">Les retours de cycle sont crédités au pas suivant. Aucun stock ne devient négatif.</p>`);return;}
 else if(a==='detailed-rules'){popup('Bienvenue au laboratoire',`<p>Votre première ligne fonctionne déjà. Observez les cartes, essayez un module, puis regardez la production changer. Vous n’avez rien à cliquer pour produire.</p><ol><li>Les cartes s’alimentent de gauche à droite. Leurs flèches ouvrent ou ferment une connexion.</li><li>Sélectionnez une carte pour lire la règle complète. Les boutons de déplacement changent l’ordre des modificateurs.</li><li>Enregistrez une configuration pour comparer vos idées. Le démontage rend les machines et la matière en tampon.</li><li>À 1 000 composants, encapsulez une invention et construisez dans la Serre. Les échanges sont automatiques.</li></ol><p>Une fin de cycle est un reçu de procédé : elle ne contient pas une deuxième copie des composants. Chaque récupérateur et échangeur ne peut agir qu’une fois sur le même reçu.</p><p>Le navigateur masqué met la simulation en pause de fait ; le temps manqué n’est pas rattrapé. La fermeture arrête la partie. Pause explicite en haut à droite.</p><p class="muted">Limites annoncées : six lignes par installation et dix machines par ligne (extensibles par brevets), réserves 10²¹, qualité ×10¹², arrêt de sécurité à 10²¹ composants cumulés. Pas de progression hors ligne.</p>`);return;}
 if(result&&before){observation=observeChange(before,plant,'Configuration modifiée');updateChallenge(state);}
 if(!result)toast('Action indisponible : vérifiez le budget, les types, les capacités de réserve, la place ou les déblocages.');
 render();
});
function lineChoices(){const cost=fmt(costOf(state,'intake')+costOf(state,'press')+laneFee(state,plant));return `<div class="line-role-options"><button data-action="add-source-line"><strong>Alimentation propre</strong><small>L’injecteur prélève dans la réserve. Coût : ${cost} composants.</small></button><button data-action="add-branch-line"><strong>Réception de branche</strong><small>Injecteur suspendu. Choisissez cette ligne comme destination d’un aiguillage. Coût : ${cost} composants.</small></button></div>`;}
function rateValue(){return measuredRate(state).rate;}
function galleryPanel(){
 if(!cloudReady())return '';
 return `<section class="panel gallery"><div class="section-head"><div><span class="eyebrow">GALERIE PARTAGÉE</span><h3>Inventions des joueurs</h3></div>${btn('gallery-refresh','Actualiser','class="subtle"')}</div><p class="muted">Chaque invention est mesurée seule, depuis des machines vides, avec toutes les familles disponibles. Votez pour celles qui vous surprennent.</p>${gallery===null?'<p class="muted">Chargement…</p>':gallery.length?`<div class="gallery-grid">${gallery.map((g,i)=>`<article class="gallery-item"><h4><span data-user-text>${esc(g.name)}</span></h4><small>${g.author?`<span data-user-text>${esc(g.author)}</span> · `:''}${fmt(g.rate)}/s · ${g.votes} ${g.votes>1?'votes':'vote'}</small><div>${btn('gallery-vote',g.voted?'★ Voté':'☆ Voter',`data-index="${i}"`,g.mine)}${btn('gallery-import','Ajouter à ma bibliothèque',`data-index="${i}" class="subtle"`)}</div></article>`).join('')}</div>`:'<p class="muted">Aucune invention publiée pour l’instant. Soyez la première personne à en partager une.</p>'}</section>`;}
function puzzlesPanel(){
 const key=dailyKey(),daily=dailyPuzzle(key),best=meta.daily[key];
 return `<section class="panel puzzles"><span class="eyebrow">APPRENDRE PAR LA PRATIQUE</span><h2>Puzzles</h2><p class="muted">Des ateliers isolés, avec quelques modules et un budget. Votre partie est mise de côté puis reprend exactement où elle en était.</p><div class="puzzle-grid">${PUZZLES.map((p,i)=>`<article class="puzzle ${meta.puzzles[p.id]!==undefined?'solved':''}"><span class="eyebrow">${String(i+1).padStart(2,'0')} ${meta.puzzles[p.id]!==undefined?`· ✓ ${time(meta.puzzles[p.id]*10)}`:''}</span><h3>${p.name}</h3><p>${p.goal}</p>${btn('puzzle-start',meta.puzzles[p.id]!==undefined?'Rejouer':'Commencer',`data-id="${p.id}"`,!!puzzle)}</article>`).join('')}<article class="puzzle daily"><span class="eyebrow">PUZZLE DU JOUR · ${key}</span><h3>${daily.allowed.map(k=>MODULES[k].name).join(' · ')}</h3><p>Budget ${daily.budget} composants. Meilleur débit mesuré.${best!==undefined?` Votre record : ${fmt(best)}/s.`:''}</p>${btn('puzzle-start','Jouer le puzzle du jour','data-id="daily" class="primary"',!!puzzle)}${cloudReady()?`<div class="leaderboard"><strong>Classement du jour</strong>${board===null?'<p class="muted">Chargement…</p>':board.length?`<ol>${board.map(r=>`<li class="${r.mine?'mine':''}"><span data-user-text>${esc(r.name||'—')}</span><b>${fmt(r.score)}/s</b></li>`).join('')}</ol>`:'<p class="muted">Aucun score aujourd’hui.</p>'}</div>`:''}</article></div></section>`;}
function puzzleBanner(){
 const p=puzzle!;const def=p.def;const progress=p.daily?0:Math.min(1,def.progress(state));
 return `<section class="puzzle-banner"><div><span class="eyebrow">${p.daily?'PUZZLE DU JOUR':'PUZZLE'} · ${def.name}</span><h2>${def.goal}</h2><p class="muted">${def.hint}</p>${p.daily?`<p>${p.score!==undefined?`Dernière mesure : <b>${fmt(p.score)}/s</b>. `:''}${meta.daily[def.id.slice(6)]!==undefined?`Record du jour : ${fmt(meta.daily[def.id.slice(6)])}/s.`:''}</p>`:`<progress max="1" value="${progress}"></progress>`}</div><div class="puzzle-actions">${p.daily?btn('daily-measure','Mesurer mon atelier','class="primary"'):''}${btn('puzzle-reset','Recommencer')}${btn('puzzle-exit','Quitter le puzzle','class="subtle"')}</div></section>`;}
function enterPuzzle(id:string){
 const daily=id==='daily';const def=daily?dailyPuzzle():PUZZLES.find(x=>x.id===id);if(!def||puzzle)return;
 save();puzzle={def,main:state,daily,won:false};state=puzzleState(def);observation=null;plant='A';selectedLane=state.plants.A.lanes[0].id;selectedMachine=0;view='atelier';
 document.documentElement.classList.add('puzzle-mode');}
function exitPuzzle(){if(!puzzle)return;state=puzzle.main;puzzle=null;observation=null;plant='A';selectedLane=state.plants.A.lanes[0]?.id??0;selectedMachine=0;view='experiments';document.documentElement.classList.remove('puzzle-mode');}
function checkPuzzle(){
 if(!puzzle||puzzle.daily||puzzle.won||!puzzle.def.test(state))return;
 puzzle.won=true;const seconds=Math.round(state.tick/10);const id=puzzle.def.id;if(meta.puzzles[id]===undefined||seconds<meta.puzzles[id])meta.puzzles[id]=seconds;saveMeta();
 const index=PUZZLES.findIndex(x=>x.id===id);const next=PUZZLES[index+1];
 popup('Puzzle résolu',`<p><strong>${puzzle.def.name}</strong> · ${time(state.tick)} de simulation.</p><p>${puzzle.def.goal}</p>${next?btn('puzzle-next','Puzzle suivant',`data-id="${next.id}" class="primary"`):''}${btn('puzzle-exit','Revenir à ma partie')}`);}
function variantChoices(action:string){
 const list:[Variant,string][]=[['standard','Partie standard'],['slow','Presses lentes : 2 s par lot'],['small','Petits lots : lot maximal 40, prime ×8 dès 40'],['nores','Sans résonance : pas de résonateur, harmoniseur dès 10']];
 return `<div class="variant-list">${list.map(([v,label],i)=>btn(action,label,`data-variant="${v}" class="${i===0?'primary':''} wide"`,i>0&&!meta.engineer)).join('')}</div>${meta.engineer?'':'<p class="tiny muted">Le mode Ingénieur s’ouvre après avoir atteint 1 000 000 composants cumulés une fois.</p>'}`;}
// Short what-if: simulate the same future with and without the module. Nothing is credited to the game.
function estimateInsertion(kind:Kind){
 try{const base=clone(state);base.paused=false;const withIt=clone(base);if(!insertModule(withIt,plant,selectedLane,kind))return null;
  withIt.plants.A.stock.components=base.plants.A.stock.components;
  const run=(x:State)=>{const start=x.produced;simulate(x,90);return x.fault?0:(x.produced-start)/90;};
  return {without:run(base),with:run(withIt)};}catch{return null;}}
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&(e.target as Element).matches('.network-machine')){e.preventDefault();(e.target as Element).dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('submit',e=>{const form=e.target as HTMLFormElement;if(form.id!=='name-form')return;e.preventDefault();const name=String(new FormData(form).get('name')??'');const ok=form.dataset.submit==='capsule'?encapsulate(state,plant,selectedLane,name):saveConfiguration(state,plant,name);if(ok){if(form.dataset.submit==='config'){preferences.guide.saved=true;savePreferences();}$<HTMLDialogElement>('#dialog').close();save();render();toast('Enregistré dans votre bibliothèque.');}else toast('Impossible : déblocage requis ou bibliothèque pleine.');});
document.addEventListener('change',e=>{const el=e.target as HTMLInputElement;
 if(el.hasAttribute('data-bench-duration')){benchDuration=Number(el.value);benchResult=null;render();return;}
 if(el.dataset.route){const before=clone(state);const m=findMachine();if(m){const key=el.dataset.route as 'target'|'mode'|'threshold';const value=key==='mode'?el.value:Number(el.value);if(!configureRouter(state,plant,selectedLane,m.id,{[key]:value}))toast('Action indisponible : vérifiez le budget, les types, les capacités de réserve, la place ou les déblocages.');}if(JSON.stringify(state)!==JSON.stringify(before)){observation=observeChange(before,plant,'Orientation modifiée');updateChallenge(state);}render();return;}
 if(el.hasAttribute('data-language')){preferences.language=el.value==='en'?'en':'fr';setLanguage(preferences.language);savePreferences();render();return;}if(el.dataset.variant){const before=clone(state);const m=findMachine();if(m&&!setVariant(state,m,Number(el.value)))toast('Réglage indisponible pour le moment.');if(JSON.stringify(state)!==JSON.stringify(before)){observation=observeChange(before,plant,'Réglage modifié');updateChallenge(state);}render();return;}
 if(el.dataset.param){const before=clone(state);const m=findMachine();if(m){if(m.working){toast('Attendez la fin de la charge avant de modifier sa durée.');render();return;}if(!setParam(state,m,Number(el.value)))toast('Réglage indisponible pour le moment.');}if(JSON.stringify(state)!==JSON.stringify(before)){observation=observeChange(before,plant,'Réglage modifié');updateChallenge(state);}render();}if(el.hasAttribute('data-plasma')){const before=clone(state);state.plants.A.plasmaOn=el.checked;observation=observeChange(before,'A','Surchauffe modifiée');render();return;}if(el.hasAttribute('data-catalyst')){const before=clone(state);state.plants.A.catalystOn=el.checked;observation=observeChange(before,'A','Catalyse modifiée');updateChallenge(state);render();}});
$<HTMLInputElement>('#import-file').addEventListener('change',async e=>{const input=e.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;try{if(file.size>2_000_000)throw Error('Fichier trop grand (maximum 2 Mo).');const candidate=deserialize(await file.text());popup('Remplacer la partie courante ?',`<p>Partie valide : ${fmt(candidate.produced)} composants cumulés, ${candidate.library.length} inventions. Votre partie actuelle sera conservée comme sauvegarde précédente.</p>${btn('confirm-import','Importer cette partie','class="primary"')}`);const confirm=$<HTMLButtonElement>('#dialog [data-action="confirm-import"]');confirm.addEventListener('click',()=>{try{persist(localStorage,candidate);state=candidate;observation=null;benchResult=null;storageBlocked=false;plant='A';selectedLane=state.plants.A.lanes[0]?.id??0;$<HTMLDialogElement>('#dialog').close();render();toast('Partie importée. Aucun temps hors ligne ajouté.');}catch(e){toast((e as Error).message);}});}catch(e){toast((e as Error).message);}input.value='';});
let previous=performance.now(),accumulator=0,pointerDown=false;
// Never rebuild the interface between a press and its release: the click would be lost.
document.addEventListener('pointerdown',()=>{pointerDown=true;},true);
for(const type of ['pointerup','pointercancel'])document.addEventListener(type,()=>{setTimeout(()=>{pointerDown=false;},0);},true);
setInterval(()=>{const now=performance.now(),elapsed=(now-previous)/1000;previous=now;if(document.hidden||state.paused||state.fault||elapsed>1){accumulator=0;return;}accumulator+=elapsed;while(accumulator>=.1){step(state);accumulator-=.1;}if(now-lastRender>=800&&!pointerDown&&!$<HTMLDialogElement>('#dialog').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName??'')){render();lastRender=now;}},50);
document.addEventListener('visibilitychange',()=>{previous=performance.now();accumulator=0;if(document.hidden)save();});
setInterval(save,5000);window.addEventListener('pagehide',save);
// Touch and mouse gestures: hold a machine, then slide it sideways to reorder; slide the machine sheet down to close it.
let drag:{id:number;x:number;timer:number;active:boolean}|null=null;
document.addEventListener('pointerdown',e=>{
 const node=(e.target as Element).closest<HTMLElement>('.node[data-id]');if(!node||e.button>0)return;
 const id=Number(node.dataset.id);drag={id,x:e.clientX,active:false,timer:window.setTimeout(()=>{if(!drag)return;drag.active=true;selectedMachine=id;try{navigator.vibrate?.(20);}catch{}render();document.querySelector(`.node[data-id="${id}"]`)?.classList.add('dragging');},450)};
});
document.addEventListener('pointermove',e=>{
 if(!drag)return;if(!drag.active){if(Math.abs(e.clientX-drag.x)>10){clearTimeout(drag.timer);drag=null;}return;}
 const dx=e.clientX-drag.x;if(Math.abs(dx)<110)return;
 const before=clone(state);if(moveModule(state,plant,selectedLane,drag.id,dx>0?1:-1)){observation=observeChange(before,plant,'Configuration modifiée');updateChallenge(state);drag.x=e.clientX;render();document.querySelector(`.node[data-id="${drag.id}"]`)?.classList.add('dragging');}else drag.x=e.clientX;
});
document.addEventListener('touchmove',e=>{if(drag?.active)e.preventDefault();},{passive:false});
for(const type of ['pointerup','pointercancel'])document.addEventListener(type,()=>{if(drag){clearTimeout(drag.timer);if(drag.active)suppressClick=true;drag=null;document.querySelector('.node.dragging')?.classList.remove('dragging');}});
let suppressClick=false;document.addEventListener('click',e=>{if(suppressClick){suppressClick=false;e.stopImmediatePropagation();e.preventDefault();}},true);
let sheet:{y:number}|null=null;
document.addEventListener('touchstart',e=>{const el=(e.target as Element).closest('.inspector.has-machine');sheet=el&&el.scrollTop<=0?{y:e.touches[0].clientY}:null;},{passive:true});
document.addEventListener('touchend',e=>{if(sheet&&e.changedTouches[0].clientY-sheet.y>90){selectedMachine=0;render();}sheet=null;},{passive:true});
applyDisplay();
render();
startCloud().then(c=>{if(c)render();});
// Installed version: offline cache, only when served over http(s) with its manifest (not the single-file or claude.ai builds).
try{if(/^https?:$/.test(location.protocol)&&document.querySelector('link[rel="manifest"]')&&'serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});}catch{}
if(typeof requestAnimationFrame==='function')startEffects({state:()=>state,plant:()=>plant,preferences:effects,music:()=>meta.music,ghost:()=>ghostBase.best[variantOf(state)],onOpen:v=>{view=v;selectedMachine=0;render();window.scrollTo({top:0,behavior:'smooth'});},onShowModule:kind=>{view='atelier';selectedMachine=0;render();const offer=kind?document.querySelector(`[data-offer="${kind}"]`):null;if(offer){offer.scrollIntoView({behavior:'smooth',block:'center'});offer.classList.add('fx-highlight');}}});
